import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Syncthing.html","title":"Syncthing","lang":"en-US","frontmatter":{},"git":{"createdTime":1681453016000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":11}]},"readingTime":{"minutes":0.25,"words":74},"filePathRelative":"Syncthing.md"}`),a={name:`Syncthing.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="syncthing" tabindex="-1"><a class="header-anchor" href="#syncthing"><span>Syncthing</span></a></h1><p><a href="https://syncthing.net/" target="_blank" rel="noopener noreferrer">公式: Syncthing</a></p><p>ローカルのファイル同士をsyncするツール。LANの中だけで通信が閉じるので安心感も強いし、 何よりAndroidのアプリなどの出来が良い。</p><p><a href="./UFASアーキテクチャ.html">UFASアーキテクチャ</a>のAndroidアプリと相性が良い。</p><h3 id="macで起動時に勝手に立ち上がるようにする" tabindex="-1"><a class="header-anchor" href="#macで起動時に勝手に立ち上がるようにする"><span>Macで起動時に勝手に立ち上がるようにする</span></a></h3><p>以前syncthing-appのアップデート周りとかが面倒でコマンドライン版を使っているが、いちいち立ち上げるのは面倒だなぁ、と思い、サービスとして使う方法を調べた。</p><p>コマンドライン版でもhomebrewでインストールしている場合は以下で良さそう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ brew services start syncthing</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>brew info syncthingするとこの辺を教えてくれる。</p><p>ちなみにwebGUIは <code>http://localhost:8384/</code> だとか。</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};